   ]},
  {"clause_id": "c043",
   "issues": [
     {"issue": "\"This shall only apply to a New York Times part or section regularly inserted in the Sunday or daily newspaper\" leaves \"This\" ambiguous between the new sixty-day written notice and the whole of Section 9B, and \"regularly inserted\" is undefined. The escape clause — no notice required if The Times \"can demonstrate that it did not have sixty (60) days' notice itself\" — supplies no standard of proof or of \"promptest practicable notice.\"", "type": 1, "prob": 0.33}
